const c = $input.first().json;
const neighborMap = c.neighbors || {};
const adjacent = Array.isArray(neighborMap[c.initial_zone]) ? neighborMap[c.initial_zone] : [];
const zones = [c.initial_zone, ...adjacent].filter((zone, i, all) => zone && all.indexOf(zone) === i).slice(0, 3);
return [{ json: { ...c, investigation_plan: { mode: 'synthetic_demo_only', evidence_scope: 'vehicle attributes and timestamps only; no facial identification', human_review_required: true, zones_to_review: zones, workers: zones.map((zone, i) => ({ worker_id: `zone_worker_${i + 1}`, jurisdiction: zone, status: 'awaiting_video_backend', candidate_sightings: [] })), follow_up_zones: zones.slice(1), sha256_integrity: 'computed_by_local_backend_when_evidence_is_attached' } } }];

const c = $input.first().json;
const plan = c.investigation_plan;
const videosByZone = new Map();
for (const video of c.registered_videos || []) {
  if (!videosByZone.has(video.jurisdiction)) videosByZone.set(video.jurisdiction, []);
  videosByZone.get(video.jurisdiction).push(video);
}
return plan.workers.flatMap((worker) => {
  const zoneNeighbors = c.neighbors?.[worker.jurisdiction] || [];
  const videos = videosByZone.get(worker.jurisdiction) || [];
  const assignments = videos.length ? videos : [null];
  return assignments.map((video) => ({ json: {
    case_id: c.case_id,
    worker_id: worker.worker_id,
    jurisdiction: worker.jurisdiction,
    status: video ? 'ready_for_analysis' : 'awaiting_local_video',
    video_source_id: video?.video_source_id || null,
    camera_id: video?.camera_id || null,
    video_recorded_at: video?.recorded_at || null,
    video_sha256: video?.sha256 || null,
    description: c.description,
    clue: c.clue || null,
    neighbors: zoneNeighbors,
    analysis_request: { description: c.description, clue: c.clue || null, attributes_only: true, exclude_face_identification: true },
    candidate_sightings: [],
    evidence_sha256: null,
    human_review: { required: true, status: 'pending' },
    follow_up_of: worker.jurisdiction === c.initial_zone ? null : c.initial_zone
  } }));
});

const input = $input.first().json;
const case_id = String(input.case_id ?? '').trim();
const description = String(input.description ?? '').trim();
const initial_zone = String(input.initial_zone ?? '').trim();
let neighbors;
try { neighbors = JSON.parse(input.neighbors_json ?? ''); } catch { throw new Error('Jurisdiction adjacency map must be valid JSON.'); }
if (!case_id || description.length < 3 || !initial_zone) throw new Error('Case ID, case description, and initial jurisdiction are required.');
if (!neighbors || typeof neighbors !== 'object' || Array.isArray(neighbors)) throw new Error('Jurisdiction adjacency map must be a JSON object.');
if (!Object.values(neighbors).every((zones) => Array.isArray(zones) && zones.every((zone) => typeof zone === 'string' && zone.trim()))) throw new Error('Each jurisdiction in the map must have an array of named neighboring jurisdictions.');
const adjacent = [...new Set((neighbors[initial_zone] || []).map((zone) => zone.trim()).filter((zone) => zone && zone !== initial_zone))];
if (adjacent.length < 2) throw new Error('The initial jurisdiction needs at least two distinct neighboring jurisdictions for the three-zone review.');
return [{ json: { case_id, description, initial_zone, neighbors } }];
